import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    pos = [0] * (n + 1)
    for i in range(1, n + 1):
        athlete = int(data[i])
        pos[athlete] = i
    sys.stdout.write("\n".join(str(pos[i]) for i in range(1, n + 1)))

if __name__ == "__main__":
    main()
